def test_all_orders_can_be_printed(capsys: pytest.CaptureFixture[str]) -> None:
    for order in ORDERS:
        print(order)

    captured = capsys.readouterr()
    printed_orders = [line for line in captured.out.splitlines() if line]
    assert printed_orders == ORDERS